async(page)=>{
 const base='E:/Dr.RouteFit/prototype/records/2026-10-24-access-control/',checks=[],errors=[];page.on('pageerror',e=>errors.push(e.message));
 const assert=(ok,msg)=>{if(!ok)throw Error(msg)};const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 const role=async r=>page.locator(`[data-role=${r}]`).first().click();const nav=async n=>page.locator(`[data-nav=${n}]`).first().click();
 const act=async(a,p={})=>{await page.locator(`[data-action=${a}]`).first().click();for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'})};
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});if(await page.locator('#exit-account-preview').count())await page.locator('#exit-account-preview').click();
 await role('dispatch');await page.locator('[data-action=qa]').first().click();await act('reset');await role('ops');await nav('inventory');await page.locator('[data-section-tab=warehouses]').click();await act('warehouseNew',{name:'演示第二仓',location:'DEMO Other warehouse'});const wh=(await state()).warehouses.at(-1).id;
 await role('dispatch');await act('create',{customer:'范围外演示客户',destination:'DEMO outside warehouse',cargo:'DEMO Box',qty:1,weight:1,length:10,width:10,height:10,amount:10,warehouseId:wh});const outside=(await state()).orders[0].id;
 await role('ops');await nav('access');await page.locator('[data-access-tab=roles]').click();await page.locator('[data-access=new]').click();await page.locator('#access-form [name=name]').fill('演示客服只读');await page.locator('[name=permissions][value="orders.read"]').check();await page.locator('#access-form [name=confirmed]').check();await page.locator('#access-form [type=submit]').click();const rid=(await state()).access.roles.at(-1).id;
 await page.locator('[data-access-tab=accounts]').click();await page.locator('[data-access=new]').click();await page.locator('#access-form [name=login]').fill('demo.support');await page.locator('#access-form [name=name]').fill('演示客服');await page.locator(`[name=roleIds][value="${rid}"]`).check();await page.locator('[name=warehouseIds][value=WH01]').check();await page.locator('[name=vehicleIds][value=V01]').check();await page.locator('#access-form [name=confirmed]').check();await page.locator('#access-form [type=submit]').click();const aid=(await state()).access.accounts.at(-1).id;
 checks.push('新增自定义只读角色及账号，分配指定仓库/车辆，保存授权记录');
 await page.locator(`[data-access-preview="${aid}"]`).click();await nav('orders');assert(await page.locator('[data-nav=finance]').count()===0,'finance menu leaked');assert(!(await page.locator('main').innerText()).includes('范围外演示客户'),'outside warehouse order leaked');assert(await page.locator('[data-action=offer]').first().isDisabled(),'read-only offer enabled');await page.screenshot({path:base+'readonly-preview.png',fullPage:true});
 await page.locator('#exit-account-preview').click();await page.locator('[data-access-preview=A02]').click();await nav('orders');assert(!(await page.locator('main').innerText()).includes('范围外演示客户'),'dispatch scope leaked');await page.locator('[data-action=offer]').first().click();assert(await page.locator('[name=vehicle][value=V02]').count()===0,'out-of-scope vehicle offered');await page.locator('[name=vehicle][value=V01]').check();await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'});let db=await state();assert(db.orders.some(o=>o.id===outside),'scoped write deleted another warehouse order');assert(db.access.audit.some(x=>x.actorId==='A02'&&x.action==='offer'),'business audit missing');
 checks.push('只读账号不能派单；列表隐藏其他仓库，派车只可选V01，写入不丢其他仓库订单');
 await page.locator('#exit-account-preview').click();await page.locator('[data-access-edit=A02]').click();await page.locator('#access-form [name=status]').selectOption('disabled');await page.locator('#access-form [name=confirmed]').check();await page.locator('#access-form [type=submit]').click();assert(await page.locator('[data-access-preview=A02]').isDisabled(),'disabled account can log in');
 await page.locator('[data-access-edit=A01]').click();await page.locator('#access-form [name=status]').selectOption('disabled');await page.locator('#access-form [name=confirmed]').check();await page.locator('#access-form [type=submit]').click();assert((await page.locator('#access-form .form-error').innerText()).includes('至少一个'),'last admin removed');await page.locator('[data-access=cancel]').click();
 await page.locator(`[data-access-edit="${aid}"]`).click();await page.locator('#access-form [name=confirmed]').check();await page.locator('[data-access=revoke]').click();
 checks.push('停用账号禁止模拟登录；保留最后一个管理员；撤销会话有记录');
 await page.locator('[data-access-tab=audit]').click();assert((await page.locator('main').innerText()).includes('accountRevoke'),'revoke audit absent');await page.screenshot({path:base+'access-audit.png',fullPage:true});
 await page.reload();await page.locator('[data-access-tab=accounts]').click();assert((await page.locator('main').innerText()).includes('demo.support'),'account not persisted');await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'page overflow');await page.screenshot({path:base+'accounts-mobile.png',fullPage:true});await page.setViewportSize({width:1440,height:1000});await page.screenshot({path:base+'accounts-desktop.png',fullPage:true});
 assert(!errors.length,errors.join('\n'));checks.push('刷新保留账号角色及审计；390px无整页横向溢出');return {status:'PASS',checks,pageErrors:errors};
}
